import {supabase,requireUser} from './cloud.js';
import {openVault,readVault,writeVault,protectVault,clearVault} from './vault.js';
import * as repository from './repository.js';
import {guide,step,clone,uid,escapeHTML as esc,safeURL,safeImage,history,templates,duplicateSteps,mergeSteps,stale,normalize} from './domain.js';
import {editImage} from './image-editor.js';
import {exportZip,importZip,download,html,markdown} from './portable.js';
const app=document.querySelector('#app');
let user,data,workspaces=[],active=null,view='guides',filter='',selected=new Set(),undoState=null,captureActive=false,recaptureId=null,busy=false,syncQueue=Promise.resolve(),writeQueue=Promise.resolve();
const $=s=>document.querySelector(s);
function toast(message){$('.toast')?.remove();const node=document.createElement('div');node.className='toast';node.setAttribute('role','status');node.textContent=message;document.body.append(node);setTimeout(()=>node.remove(),6000)}
function error(e){toast(e.message||String(e));setStatus('Needs attention')}
function setStatus(message){const node=$('#save-status');if(node)node.textContent=message}
function modal(title,body,actions=[]){const d=document.createElement('dialog');d.innerHTML=`<div class="dialog-head"><h2>${esc(title)}</h2><button data-close aria-label="Close dialog">×</button></div><div class="dialog-body">${body}</div><div class="dialog-actions">${actions.map((a,i)=>`<button data-action="${i}" class="${a.primary?'primary':''}">${esc(a.label)}</button>`).join('')}</div>`;document.body.append(d);d.showModal();d.querySelector('[data-close]').onclick=()=>d.close();d.onclose=()=>d.remove();actions.forEach((a,i)=>d.querySelector(`[data-action="${i}"]`).onclick=async e=>{e.target.disabled=true;try{await a.run(d)}catch(err){error(err)}finally{e.target.disabled=false}});return d}
async function persist(){const snapshot=clone(data);writeQueue=writeQueue.catch(()=>{}).then(()=>writeVault(snapshot));await writeQueue;setStatus('Saved on this device');}
async function changed(reset=false){if(!active)return;active.dirty=true;active.updatedAt=new Date().toISOString();if(reset)undoState=history(active);else undoState?.record(active);await persist();if(data.cloudSync)sync(active).catch(error)}
function mutate(fn,reset=false){fn();changed(reset).catch(error);render()}
async function sync(doc){const snapshot=clone(doc);syncQueue=syncQueue.catch(()=>{}).then(async()=>{setStatus('Syncing…');snapshot.revision=doc.revision;const result=await repository.syncGuide(snapshot);doc.revision=result.revision;doc.steps.forEach(s=>{const remote=result.paths.find(p=>p.id===s.id);if(remote)for(const f of ['screenshotPath','audioPath','videoPath'])if(remote[f])s[f]=remote[f]});doc.dirty=JSON.stringify({...doc,revision:snapshot.revision,steps:snapshot.steps})!==JSON.stringify(snapshot);doc.dirty=doc.updatedAt!==snapshot.updatedAt;await persist();setStatus(doc.dirty?'Newer edits saved locally':'Synced to cloud');});return syncQueue}
async function openGuide(id){const found=data.guides.find(g=>g.id===id);if(!found)return;active=found;try{const hydrated=await repository.hydrate(found);Object.assign(found,hydrated)}catch(e){toast('Some cloud images are unavailable offline. Your saved local images remain available.')}undoState=history(active);selected.clear();view='editor';render()}
function shell(content){app.innerHTML=`<header class="app-header"><a class="brand" href="index.html"><img src="assets/apple-touch-icon.png" alt="">Pathira</a><nav aria-label="Main navigation">${['guides','team','learning','settings'].map(v=>`<button data-nav="${v}" aria-current="${view===v}">${v[0].toUpperCase()+v.slice(1)}</button>`).join('')}</nav><span class="status" id="save-status">${navigator.onLine?'Saved on this device':'Offline · local editing available'}</span><button id="signout">Sign out</button></header><main class="layout">${content}</main>`;document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{view=b.dataset.nav;render()});$('#signout').onclick=async()=>{await writeQueue;await supabase.auth.signOut();location.href='login.html'};}
function render(){if(view==='editor'&&active)return renderEditor();if(view==='team')return renderTeam();if(view==='learning')return renderLearning();if(view==='settings')return renderSettings();renderLibrary()}
function renderLibrary(){const rows=data.guides.filter(g=>`${g.title} ${g.category} ${g.folder} ${(g.tags||[]).join(' ')} ${g.steps.map(s=>s.title+' '+s.description).join(' ')}`.toLowerCase().includes(filter.toLowerCase()));shell(`<div class="topline"><div><p class="eyebrow">Your team's working knowledge</p><h1>Make the next step clear.</h1><p class="muted">Capture once. Refine, protect, and share with confidence.</p></div><div class="toolbar"><button id="import-project">Import project</button><button class="primary" id="new-guide">＋ Create guide</button></div></div><div class="toolbar"><input id="search-guides" aria-label="Search guides, tags, folders, and steps" placeholder="Search guides, folders, tags, or instructions…" value="${esc(filter)}"><button id="refresh-cloud">Refresh cloud</button><button id="sync-all">Sync changes</button></div><div class="cards">${rows.map(g=>`<article class="guide-card"><div class="badge-line"><span class="pill">${esc(g.folder||g.category)}</span>${g.dirty?'<span class="pill warn">Local changes</span>':''}${stale(g)?'<span class="pill warn">Review due</span>':''}</div><h2><button class="open-guide" data-open="${g.id}">${esc(g.title)}</button></h2><p class="muted">${g.steps.length} steps · ${(g.tags||[]).map(esc).join(', ')||'No tags'}</p><div class="card-footer"><small>Revision ${g.revision||0}</small><button data-preview="${g.id}">Preview →</button></div></article>`).join('')||'<div class="empty"><h2>Your first guide starts here.</h2><p>Create a guide or import a portable project. New work is saved privately on this device until you sync or publish it.</p></div>'}</div>`);
 $('#search-guides').oninput=e=>{filter=e.target.value;const pos=e.target.selectionStart;renderLibrary();$('#search-guides').focus();$('#search-guides').setSelectionRange(pos,pos)};$('#new-guide').onclick=createGuide;$('#import-project').onclick=importProject;$('#refresh-cloud').onclick=()=>refreshCloud().catch(error);$('#sync-all').onclick=async()=>{try{for(const g of data.guides.filter(g=>g.dirty))await sync(g);render();toast('Changes synced')}catch(e){error(e)}};document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openGuide(b.dataset.open));document.querySelectorAll('[data-preview]').forEach(b=>b.onclick=()=>preview(data.guides.find(g=>g.id===b.dataset.preview)))}
async function refreshCloud(){const remote=await repository.fetchGuides();const localById=new Map(data.guides.map(g=>[g.id,g]));for(const g of remote)if(!localById.get(g.id)?.dirty)localById.set(g.id,g);data.guides=[...localById.values()];await persist();render();toast('Cloud guides refreshed; unsynced local changes preserved')}
function createGuide(){modal('Create a guide',`<label>Guide title<input id="new-title" placeholder="e.g. Approve a customer refund"></label><label>Template<select id="new-template"><option>Blank</option>${Object.keys(templates).map(x=>`<option>${x}</option>`).join('')}</select></label><label>Workspace<select id="new-workspace">${workspaces.map(w=>`<option value="${w.id}">${esc(w.name)}</option>`).join('')||`<option value="${data.workspaceId||''}">Local workspace</option>`}</select></label>`,[{label:'Create guide',primary:true,run:async d=>{const g=guide(d.querySelector('#new-title').value||'Untitled guide',d.querySelector('#new-workspace').value||data.workspaceId);const t=d.querySelector('#new-template').value;if(templates[t])g.steps=templates[t].map(x=>step(x));data.guides.unshift(g);await persist();d.close();await openGuide(g.id)}}])}
function imageMarkup(s){const src=safeImage(s.screenshot);if(!src)return '<p class="muted">No screenshot yet. Capture, replace, or add an image.</p>';const r=s.click?.rect;return `<div class="step-image"><img src="${src}" alt="${esc(s.alt||s.title)}">${r&&s.click.width?`<span class="click-highlight" style="left:${100*r.x/s.click.width}%;top:${100*r.y/s.click.height}%;width:${100*r.w/s.click.width}%;height:${100*r.h/s.click.height}%;border-color:${/^#[a-f0-9]{6}$/i.test(r.color)?r.color:'#ff654d'}"></span>`:''}</div>`}
function renderEditor(){const g=active;shell(`<div class="topline"><div style="flex:1;width:100%"><button id="back-guides">← Guides</button><p class="eyebrow" style="margin-top:20px">${esc(g.category)} · Revision ${g.revision||0}</p><input id="guide-name" class="title-edit" aria-label="Guide title" value="${esc(g.title)}"></div><div class="toolbar"><button id="undo">Undo</button><button id="redo">Redo</button><button id="preview-guide">Preview</button><button id="publish-guide" class="primary">Publish & share</button></div></div><div class="editor-grid"><section><div class="toolbar"><button id="capture" class="${captureActive?'recording':'primary'}">${captureActive?'■ Stop capture':'● Capture browser'}</button><button id="record-desktop">Capture screen</button><button id="bulk-duplicate">Duplicate selected</button><button id="bulk-merge">Merge selected</button><button id="bulk-delete">Delete selected</button></div>${g.steps.map((s,i)=>`<article class="step-card ${selected.has(s.id)?'selected':''} ${esc(s.type||'step')}" data-step="${esc(s.id)}"><div class="step-header"><input type="checkbox" aria-label="Select step ${i+1}" data-select="${esc(s.id)}" ${selected.has(s.id)?'checked':''}><span class="step-number">${i+1}</span><select aria-label="Step type" data-field="type">${['step','section','callout','warning'].map(v=>`<option ${s.type===v?'selected':''}>${v}</option>`).join('')}</select><button data-move="-1" aria-label="Move step up" ${i===0?'disabled':''}>↑</button><button data-move="1" aria-label="Move step down" ${i===g.steps.length-1?'disabled':''}>↓</button></div><div class="step-content"><input class="step-title" data-field="title" aria-label="Step ${i+1} title" value="${esc(s.title)}">${imageMarkup(s)}${s.captureWarning?`<p class="notice">${esc(s.captureWarning)}</p>`:''}<textarea data-field="description" aria-label="Step ${i+1} instructions" placeholder="Explain the action and the expected result…">${esc(s.description)}</textarea><div class="step-actions"><button data-image-edit ${s.screenshot?'':'disabled'}>Edit image</button><button data-replace>Replace image</button><button data-recapture>Recapture step</button><button data-branch>Branches</button><button data-block>Save reusable block</button><button data-narrate>Record narration</button><button data-delete class="danger">Delete</button></div><label>Image description<input data-field="alt" value="${esc(s.alt||'')}" placeholder="Describe the image for screen readers"></label><label>Source URL<input data-field="url" value="${esc(s.url||'')}" placeholder="https://…"></label>${/^data:audio\/[\w.+-]+;base64,[A-Za-z0-9+/=\s]+$/.test(s.audio||'')?`<audio controls src="${s.audio}"></audio>`:''}${/^data:video\/[\w.+-]+;base64,[A-Za-z0-9+/=\s]+$/.test(s.video||'')?`<video controls style="max-width:100%" src="${s.video}"></video>`:''}${s.branches?.length?`<small>${s.branches.length} conditional path(s)</small>`:''}</div></article>`).join('')}<div class="toolbar"><button id="add-step">＋ Add step</button><button id="insert-block">Insert reusable block</button><button id="split-guide">Split at selected step</button><button id="merge-guide">Merge another guide</button></div></section><aside class="sidebar"><section class="panel side-fields"><h3>Guide details</h3><label>Folder<input id="guide-folder" value="${esc(g.folder||'')}"></label><label>Tags<input id="guide-tags" value="${esc((g.tags||[]).join(', '))}"></label><label>Category<input id="guide-category" value="${esc(g.category)}"></label><button id="guide-variables">Variables</button><button id="sync-guide">Sync to cloud</button><button id="guide-history">Version history</button><button id="guide-review">Mark reviewed today</button></section><section class="panel side-fields"><h3>Ownership</h3><button id="export-project">Export project ZIP</button><button id="export-html">Export HTML</button><button id="export-md">Export Markdown</button><button id="delete-guide" class="danger">Delete guide permanently</button></section></aside></div>`);
 $('#back-guides').onclick=()=>{view='guides';render()};$('#guide-name').onchange=e=>{g.title=e.target.value;changed().catch(error)};for(const [id,key]of [['guide-folder','folder'],['guide-category','category']])$('#'+id).onchange=e=>{g[key]=e.target.value;changed().catch(error)};$('#guide-tags').onchange=e=>{g.tags=e.target.value.split(',').map(x=>x.trim()).filter(Boolean);changed().catch(error)};
 $('#undo').onclick=()=>restoreHistory('undo');$('#redo').onclick=()=>restoreHistory('redo');$('#preview-guide').onclick=()=>preview(g);$('#publish-guide').onclick=publishGuide;$('#capture').onclick=()=>{window.postMessage({type:captureActive?'PATHIRA_STOP_CAPTURE':'PATHIRA_START_CAPTURE'},location.origin);setTimeout(()=>{if(!captureActive)toast('Open the Pathira extension side panel to start or resume recording.')},900)};$('#record-desktop').onclick=captureScreen;
 $('#bulk-duplicate').onclick=()=>mutate(()=>g.steps=duplicateSteps(g.steps,selected));$('#bulk-merge').onclick=()=>{try{mutate(()=>g.steps=mergeSteps(g.steps,selected))}catch(e){error(e)}};$('#bulk-delete').onclick=()=>{if(selected.size&&confirm(`Delete ${selected.size} selected steps?`))mutate(()=>g.steps=g.steps.filter(s=>!selected.has(s.id)))};
 document.querySelectorAll('[data-step]').forEach(card=>{const s=g.steps.find(s=>s.id===card.dataset.step);card.querySelector('[data-select]').onchange=e=>{e.target.checked?selected.add(s.id):selected.delete(s.id);card.classList.toggle('selected',e.target.checked)};card.querySelectorAll('[data-field]').forEach(input=>input.onchange=e=>{s[input.dataset.field]=e.target.value;changed().catch(error)});card.querySelectorAll('[data-move]').forEach(b=>b.onclick=()=>mutate(()=>{const from=g.steps.indexOf(s),to=from+Number(b.dataset.move);[g.steps[from],g.steps[to]]=[g.steps[to],g.steps[from]]}));card.querySelector('[data-delete]').onclick=()=>mutate(()=>g.steps=g.steps.filter(x=>x!==s));card.querySelector('[data-replace]').onclick=()=>replaceImage(s);card.querySelector('[data-image-edit]').onclick=async()=>{try{const result=await editImage(s.screenshot,s.click);if(result)mutate(()=>{if(result.redacted){delete s.original;delete s.imageHistory;}else s.original=s.original||s.screenshot;s.screenshot=result.screenshot;s.click=result.click;delete s.screenshotPath;},result.redacted)}catch(e){error(e)}};card.querySelector('[data-recapture]').onclick=()=>{recaptureId=s.id;window.postMessage({type:'PATHIRA_START_CAPTURE'},location.origin);toast('Capture replacement steps, then stop. The first replaces this screenshot.')};card.querySelector('[data-branch]').onclick=()=>branches(s);card.querySelector('[data-block]').onclick=async()=>{data.blocks=[...(data.blocks||[]),{...clone(s),id:uid()}];await persist();toast('Reusable block saved locally')};card.querySelector('[data-narrate]').onclick=()=>recordMedia(s,'audio');});
 $('#add-step').onclick=()=>mutate(()=>g.steps.push(step()));$('#insert-block').onclick=insertBlock;$('#split-guide').onclick=splitGuide;$('#merge-guide').onclick=mergeGuide;$('#guide-variables').onclick=variables;$('#sync-guide').onclick=()=>sync(g).then(render).catch(error);$('#guide-history').onclick=versionHistory;$('#guide-review').onclick=()=>mutate(()=>g.reviewedAt=new Date().toISOString());$('#export-project').onclick=()=>download(exportZip(g),'pathira-project.zip','application/zip');$('#export-html').onclick=()=>download(html(g),'guide.html','text/html');$('#export-md').onclick=()=>download(markdown(g),'guide.md','text/markdown');$('#delete-guide').onclick=deleteGuide;
}
function restoreHistory(direction){const restored=undoState[direction]();if(!restored)return;const revision=active.revision;Object.assign(active,restored,{revision,dirty:true,updatedAt:new Date().toISOString()});persist().catch(error);render()}
function replaceImage(s){const input=document.createElement('input');input.type='file';input.accept='image/png,image/jpeg,image/webp';input.onchange=async()=>{try{const file=input.files[0];if(!file)return;if(file.size>20*1024*1024)throw Error('Image must be under 20 MB');const value=await repository.blobData(file);if(!safeImage(value))throw Error('Unsupported image type');mutate(()=>{s.original=s.original||s.screenshot;s.screenshot=value;s.click={};delete s.screenshotPath})}catch(e){error(e)}};input.click()}
function branches(s){const d=modal('Conditional paths',`<p>Choose where the learner goes next. The default path continues to the following step.</p><div id="branch-rows">${(s.branches||[]).map((b,i)=>branchRow(b,i)).join('')}</div><button id="add-branch">Add path</button>`,[{label:'Save paths',primary:true,run:async d=>{mutate(()=>s.branches=[...d.querySelectorAll('.branch-row')].map(row=>({label:row.querySelector('input').value,target:row.querySelector('select').value})).filter(b=>b.label));d.close()}}]);d.querySelector('#add-branch').onclick=()=>d.querySelector('#branch-rows').insertAdjacentHTML('beforeend',branchRow({},0));}
function branchRow(b){return `<div class="branch-row inline"><input aria-label="Path label" placeholder="If approved…" value="${esc(b.label||'')}"><select aria-label="Destination step">${active.steps.map(s=>`<option value="${esc(s.id)}" ${b.target===s.id?'selected':''}>${esc(s.title)}</option>`).join('')}</select></div>`}
function variables(){modal('Reusable variables',`<p>Use {{variable}} in titles and instructions.</p><label>Variables as JSON<textarea id="variables" rows="8">${esc(JSON.stringify(active.variables||{},null,2))}</textarea></label>`,[{label:'Save',primary:true,run:async d=>{const v=JSON.parse(d.querySelector('textarea').value);if(!v||Array.isArray(v)||typeof v!=='object'||Object.values(v).some(x=>typeof x!=='string'))throw Error('Use an object with text values');mutate(()=>active.variables=v);d.close()}}])}
function insertBlock(){const blocks=data.blocks||[];if(!blocks.length)return toast('Save a step as a reusable block first');modal('Insert reusable block',`<select id="choose-block">${blocks.map((b,i)=>`<option value="${i}">${esc(b.title)}</option>`).join('')}</select>`,[{label:'Insert',primary:true,run:async d=>{mutate(()=>active.steps.push({...clone(blocks[Number(d.querySelector('select').value)]),id:uid()}));d.close()}}])}
async function splitGuide(){const index=active.steps.findIndex(s=>selected.has(s.id));if(index<1)return toast('Select a step after the first step to split here');const g=guide(active.title+' — part 2',active.workspaceId);g.steps=clone(active.steps.slice(index));data.guides.unshift(g);mutate(()=>active.steps=active.steps.slice(0,index));toast('Second guide created')}
function mergeGuide(){const others=data.guides.filter(g=>g.id!==active.id);if(!others.length)return toast('Create another guide first');modal('Merge a copy of another guide',`<select>${others.map((g,i)=>`<option value="${i}">${esc(g.title)}</option>`).join('')}</select><p>The source guide remains available.</p>`,[{label:'Merge',primary:true,run:async d=>{const source=await repository.hydrate(others[Number(d.querySelector('select').value)]);const mapping=new Map(source.steps.map(s=>[s.id,uid()]));mutate(()=>active.steps.push(...source.steps.map(s=>({...clone(s),id:mapping.get(s.id),branches:(s.branches||[]).map(b=>({...b,target:mapping.get(b.target)||b.target}))}))));d.close()}}])}
async function versionHistory(){try{const versions=(await repository.query('guide_versions',{guide_id:active.id})).sort((a,b)=>b.revision-a.revision);modal('Version history',versions.length?`<select id="version">${versions.map((v,i)=>`<option value="${i}">Revision ${v.revision} · ${new Date(v.created_at).toLocaleString()}</option>`).join('')}</select><p>Restore creates a new revision. Later versions remain in history.</p><pre id="version-diff"></pre>`:'<p>Sync this guide to create its first cloud revision.</p>',versions.length?[{label:'Compare selected',run:async d=>{const old=versions[Number(d.querySelector('select').value)].snapshot;d.querySelector('pre').textContent=`Title: ${old.title} → ${active.title}\nSteps: ${old.steps.length} → ${active.steps.length}\nChanged instructions: ${active.steps.filter(s=>JSON.stringify(s)!==JSON.stringify(old.steps.find(x=>x.id===s.id))).length}`;}},{label:'Restore selected',primary:true,run:async d=>{const old=await repository.hydrate(versions[Number(d.querySelector('select').value)].snapshot);const revision=active.revision;mutate(()=>Object.assign(active,old,{revision}));await sync(active);d.close();render()}}]:[])}catch(e){error(e)}}
async function importProject(){const input=document.createElement('input');input.type='file';input.accept='.zip';input.onchange=async()=>{try{if(!input.files[0])return;const g=await importZip(input.files[0],data.workspaceId);data.guides.unshift(g);await persist();await openGuide(g.id)}catch(e){error(e)}};input.click()}
async function deleteGuide(){if(!confirm('Permanently delete this guide, cloud versions, published link, comments, and media? Export a backup first if needed.'))return;try{await repository.deleteCloudGuide(active);data.guides=data.guides.filter(g=>g.id!==active.id);active=null;await persist();view='guides';render();toast('Guide deleted')}catch(e){error(e)}}
function preview(doc){sessionStorage.setItem('pathira-preview',JSON.stringify(doc));location.href='view.html?preview=1'}
async function publishGuide(){const d=modal('Publish a reviewed copy',`<p>Viewers can open a public guide without an account. Only this published snapshot is shared; later edits require publishing again.</p><label>Optional password<input id="share-password" type="password" autocomplete="new-password"></label><label>Expiration<input id="share-expiry" type="datetime-local"></label><label>Restrict to verified email domain<input id="share-domain" placeholder="company.com"></label><label class="inline"><input id="share-reviewed" type="checkbox">I reviewed the guide and images for sensitive information.</label><p id="share-result" role="status"></p>`,[{label:'Revoke current link',run:async()=>{await repository.rpc('revoke_share',{g:active.id});toast('Published link revoked')}},{label:'Publish',primary:true,run:async d=>{if(!d.querySelector('#share-reviewed').checked)throw Error('Review the guide and check the confirmation first.');await sync(active);active.branding=workspaces.find(w=>w.id===active.workspaceId)?.branding||{};const token=await repository.publish(active,{password:d.querySelector('#share-password').value,expiry:d.querySelector('#share-expiry').value?new Date(d.querySelector('#share-expiry').value).toISOString():null,domain:d.querySelector('#share-domain').value});const url=new URL('view.html',location.href);url.searchParams.set('share',token);const result=d.querySelector('#share-result');result.textContent='';const a=document.createElement('a');a.href=url;a.textContent=url;result.append(a);const pre=document.createElement('pre');pre.textContent=`<iframe src="${url}" title="${active.title.replaceAll('"','')}" width="100%" height="700" loading="lazy"></iframe>`;result.append(pre);await navigator.clipboard?.writeText(url.toString()).catch(()=>{});toast('Published link copied')} }]);}
async function captureScreen(){try{const stream=await navigator.mediaDevices.getDisplayMedia({video:true});const video=document.createElement('video');video.srcObject=stream;await video.play();const c=document.createElement('canvas');c.width=video.videoWidth;c.height=video.videoHeight;c.getContext('2d').drawImage(video,0,0);stream.getTracks().forEach(t=>t.stop());mutate(()=>active.steps.push({...step('Screen capture'),screenshot:c.toDataURL('image/png')}));toast('Review and redact the screenshot before syncing or publishing.')}catch(e){if(e.name!=='NotAllowedError')error(e)}}
async function recordMedia(s,kind){try{const stream=kind==='audio'?await navigator.mediaDevices.getUserMedia({audio:true}):await navigator.mediaDevices.getDisplayMedia({video:true,audio:true});const chunks=[],recorder=new MediaRecorder(stream);recorder.ondataavailable=e=>chunks.push(e.data);const d=modal(kind==='audio'?'Recording narration':'Recording video','<p>Recording is active. Stop when finished. Record only content you are permitted to capture.</p>',[{label:'Stop and save',primary:true,run:async()=>recorder.stop()}]);recorder.onstop=async()=>{stream.getTracks().forEach(t=>t.stop());const blob=new Blob(chunks,{type:recorder.mimeType});if(blob.size>20*1024*1024){d.close();return toast('Recording exceeds 20 MB. Try a shorter recording.')}const value=await repository.blobData(blob);mutate(()=>s[kind]=value);d.close()};d.addEventListener('close',()=>{if(recorder.state==='recording')recorder.stop()});recorder.start();setTimeout(()=>{if(recorder.state==='recording')recorder.stop()},120000)}catch(e){if(e.name!=='NotAllowedError')error(e)}}
async function renderTeam(){shell('<h1>Team</h1><div id="team-content">Loading workspace…</div>');try{const members=await repository.query('workspace_members',{workspace_id:data.workspaceId});$('#team-content').innerHTML=`<p>Workspace owner: ${esc(workspaces.find(w=>w.id===data.workspaceId)?.owner_id||user.id)}</p><button id="invite">Create invitation link</button><ul>${members.map(m=>`<li>${esc(m.user_id)} · ${esc(m.role)} <button data-member="${m.user_id}">Change role</button></li>`).join('')}</ul><p>Invitation links expire after seven days and require the invited email to be verified. No email is sent automatically.</p>`;$('#invite').onclick=()=>modal('Invite a teammate','<label>Email<input id="email" type="email"></label><label>Role<select id="role"><option>viewer</option><option>editor</option><option>admin</option></select></label><p id="invite-result"></p>',[{label:'Create link',run:async d=>{const token=await repository.rpc('invite_member',{w:data.workspaceId,email:d.querySelector('#email').value,member_role:d.querySelector('#role').value});d.querySelector('#invite-result').textContent=new URL(`workspace.html?invite=${token}`,location.href).href}}]);document.querySelectorAll('[data-member]').forEach(b=>b.onclick=()=>modal('Change member role','<select><option>viewer</option><option>editor</option><option>admin</option><option value="">Remove member</option></select>',[{label:'Save',run:async d=>{await repository.rpc('set_member',{w:data.workspaceId,u:b.dataset.member,member_role:d.querySelector('select').value||'remove'});d.close();renderTeam()}}]));}catch(e){$('#team-content').textContent=e.message}}
async function renderLearning(){shell('<h1>Learning & feedback</h1><div id="learning-content">Loading…</div>');try{const [assignments,events,comments]=await Promise.all([repository.query('guide_assignments'),repository.query('guide_events'),repository.query('guide_comments')]);$('#learning-content').innerHTML=`<p>${events.filter(e=>e.kind==='view').length} sessions opened · ${events.filter(e=>e.kind==='complete').length} completions · ${comments.filter(c=>c.kind==='outdated').length} outdated reports</p><button id="assign">Assign a guide</button><h2>Assignments</h2>${assignments.map(a=>`<article class="panel"><strong>${esc(data.guides.find(g=>g.id===a.guide_id)?.title||a.guide_id)}</strong><p>Assigned to ${esc(a.assignee_id)} · Due ${esc(a.due_at||'anytime')} · ${a.completed_at?'Complete':a.due_at&&a.due_at<new Date().toISOString().slice(0,10)?'Overdue':'Pending'}</p>${a.assignee_id===user.id&&!a.completed_at?`<button data-complete="${a.id}">Mark completed</button>`:''}</article>`).join('')||'<p>No assignments yet.</p>'}<h2>Feedback</h2>${comments.map(c=>`<article class="panel"><strong>${esc(c.kind)}</strong><p>${esc(c.body)}</p><small>${esc(c.guide_id)} · ${esc(c.step_id||'Guide')}</small></article>`).join('')||'<p>No feedback yet.</p>'}`;$('#assign').onclick=()=>modal('Assign a guide',`<label>Synced guide<select id="assign-guide">${data.guides.filter(g=>g.revision).map(g=>`<option value="${g.id}">${esc(g.title)}</option>`).join('')}</select></label><label>Teammate user ID<input id="assignee" value="${user.id}"></label><label>Due date<input id="due" type="date"></label>`,[{label:'Assign',run:async d=>{await repository.rpc('assign_guide',{g:d.querySelector('#assign-guide').value,u:d.querySelector('#assignee').value,due:d.querySelector('#due').value||null});d.close();renderLearning()}}]);document.querySelectorAll('[data-complete]').forEach(b=>b.onclick=async()=>{try{await repository.rpc('complete_assignment',{a:b.dataset.complete});renderLearning()}catch(e){error(e)}})}catch(e){$('#learning-content').textContent=e.message}}
function renderSettings(){shell(`<h1>Privacy & settings</h1><div class="settings-grid"><section class="panel"><h2>Cloud sync</h2><p>Guides are encrypted in this browser. Cloud sync stores edited media and version history in your team's private Supabase workspace. It is not end-to-end encrypted.</p><label><input id="auto-sync" type="checkbox" ${data.cloudSync?'checked':''}> Automatically sync future edits</label><p>Review sensitive information before enabling. Earlier cloud versions may contain images from before redaction; deleting a guide removes its cloud history.</p></section><section class="panel"><h2>Device vault</h2><p>The default encryption key is stored in this browser profile. Add a separate passphrase for protection when the vault is locked. This does not change your login password. A forgotten vault passphrase cannot be recovered.</p><button id="protect">Set vault passphrase</button><button id="clear-device" class="danger">Remove this device's data</button></section><section class="panel"><h2>Workspace branding</h2><label>Display name<input id="brand-name" value="${esc(workspaces.find(w=>w.id===data.workspaceId)?.branding?.name||'Pathira')}"></label><button id="save-brand">Save branding</button></section><section class="panel"><h2>Service availability</h2><p>No paid subscription or automated billing is enabled. Translation and AI drafting require an explicitly configured provider. Scheduled email reminders, webhooks, and MCP hosting are not enabled.</p><p>Export ZIP, HTML, and Markdown from each guide at any time.</p></section></div>`);$('#auto-sync').onchange=async e=>{data.cloudSync=e.target.checked;await persist()};$('#protect').onclick=()=>modal('Protect this device vault','<label>New vault passphrase (12+ characters)<input type="password" autocomplete="new-password"></label><p>Export a backup first. This passphrase is separate from your account login.</p>',[{label:'Protect vault',run:async d=>{await writeQueue;await protectVault(d.querySelector('input').value);d.close();toast('Vault passphrase enabled')}}]);$('#clear-device').onclick=async()=>{if(confirm('Delete all guides and blocks saved on this device? Unsynced work will be lost. Cloud data is retained.')){await writeQueue;await clearVault();location.reload()}};$('#save-brand').onclick=async()=>{try{const brand={name:$('#brand-name').value};await repository.rpc('brand_workspace',{w:data.workspaceId,brand});const w=workspaces.find(w=>w.id===data.workspaceId);if(w)w.branding=brand;toast('Branding saved. Republish guides to update their snapshots.')}catch(e){error(e)}}}
let importQueue=Promise.resolve();
window.addEventListener('message',event=>{if(event.source!==window||event.origin!==location.origin||!data)return;const message=event.data;if(message?.type==='PATHIRA_CAPTURE_STATUS'){captureActive=!!message.active;if(view==='editor')render()}if(message?.type==='PATHIRA_CAPTURE_RESULT'&&message.steps?.length){importQueue=importQueue.catch(()=>{}).then(async()=>{let target=data.guides.find(g=>(g.batches||[]).includes(message.batchId));if(!target){target=active||guide('Captured workflow',data.workspaceId);if(!data.guides.includes(target))data.guides.unshift(target);const incoming=message.steps.map(s=>({...step(s.title||'Captured step'),...s,id:s.id||uid()}));if(recaptureId){const existing=target.steps.find(s=>s.id===recaptureId);if(existing&&incoming[0]){existing.screenshot=incoming[0].screenshot;existing.captureWarning=incoming[0].captureWarning;delete existing.screenshotPath;}recaptureId=null}else{const ids=new Set(target.steps.map(s=>s.id));target.steps.push(...incoming.filter(s=>!ids.has(s.id)))}target.batches=[...(target.batches||[]),message.batchId].filter(Boolean);target.dirty=true;target.updatedAt=new Date().toISOString();await persist()}window.postMessage({type:'PATHIRA_ACK_IMPORT',batchId:message.batchId},location.origin);captureActive=false;await openGuide(target.id);toast('Capture saved privately on this device. Review before syncing.');}).catch(error)}});
async function start(){try{user=await requireUser();try{await openVault(user.id)}catch(e){if(e.message!=='VAULT_LOCKED')throw e;app.innerHTML='<main class="layout"><h1>Unlock your device vault</h1><form><label>Vault passphrase<input type="password" required></label><button>Unlock</button><p role="alert"></p></form></main>';await new Promise(resolve=>{$('form').onsubmit=async e=>{e.preventDefault();try{await openVault(user.id,$('input').value);resolve()}catch(err){$('[role=alert]').textContent=err.message}}})}data=await readVault();try{const init=await repository.initialize();data.workspaceId=init.workspaceId;workspaces=init.workspaces;const invite=new URLSearchParams(location.search).get('invite');if(invite){await repository.rpc('accept_invite',{t:invite});window.history.replaceState?.({},'',location.pathname)}if(!data.migrated){const legacy=await repository.legacyGuides(user.id,data.workspaceId);data.guides.push(...legacy.filter(g=>!data.guides.some(x=>x.sourceId===g.sourceId)));data.migrated=true}await persist();}catch(e){toast('Cloud workspace unavailable. Local editing and exports are available.')}render();window.postMessage({type:'PATHIRA_GET_PENDING'},location.origin)}catch(e){app.textContent=e.message}}
start();
